1	package retention
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7	)
8	
9	// RegisterInput 是登记一份档案所需的信息。
10	//
11	// 编号和类别不能是空白；日期必须是 ParseDate 能解析的真实日期；
12	// 截止日可以与起算日相同，但不能更早。
13	type RegisterInput struct {
14		ID       string
15		Category string
16		Start    Date
17		End      Date
18	}
19	
20	// FreezeInput 是为档案新增一条冻结所需的信息。
21	type FreezeInput struct {
22		ArchiveID string
23		FreezeID  string
24		Reason    string
25		FrozenOn  Date
26	}
27	
28	// ReleaseInput 是解除一条冻结所需的信息。
29	type ReleaseInput struct {
30		ArchiveID  string
31		FreezeID   string
32		Reason     string
33		ReleasedOn Date
34	}
35	
36	// ReviseInput 是一次保管截止日修订所需的信息。
37	//
38	// 修订编号在整个保管库内唯一，且与销毁申请编号互不占用；
39	// OriginalEnd 是调用者看到的当前截止日，用于发现他人已改动期限；
40	// NewEnd 不能早于起算日，也不能等于所提交的原截止日；
41	// RevisedOn 仅用于记录，提交成功即采用新期限。
42	// 编号与原因去除首尾空白后不得为空白，文本比较以去空白后的值为准。
43	type ReviseInput struct {
44		RevisionID  string
45		ArchiveID   string
46		OriginalEnd Date
47		NewEnd      Date
48		RevisedOn   Date
49		Reason      string
50	}
51	
52	// DestructionRequest 是一次销毁申请。
53	//
54	// 一次申请可以选择多个档案。申请编号在所有成功申请中唯一，
55	// 处理日期即判断档案是否到期所依据的日期。
56	type DestructionRequest struct {
57		ApplicationID string
58		ProcessedOn   Date
59		ArchiveIDs    []string
60	}
61	
62	// CheckRequest 是销毁前一次只做核对的请求，字段含义与 DestructionRequest 相同。
63	//
64	// 核对不销毁任何档案、不生成或改写清册，也不占用申请编号：
65	// 核对失败或发现阻碍后，仍可沿用同一编号继续核对或正式提交。
66	type CheckRequest struct {
67		ApplicationID string
68		ProcessedOn   Date
69		ArchiveIDs    []string
70	}
71	
72	// normalizeText 去除首尾空白；空白字段统一按空白处理，避免同值异写。
73	func normalizeText(s string) string { return strings.TrimSpace(s) }
74	
75	func requireText(value, name string) (string, error) {
76		v := normalizeText(value)
77		if v == "" {
78			return "", fmt.Errorf("retention: %s不能为空白: %w", name, ErrBlankField)
79		}
80		return v, nil
81	}
82	
83	func requireDate(d Date, name string) error {
84		if d.IsZero() {
85			return fmt.Errorf("retention: %s缺失或无效，应为 YYYY-MM-DD: %w", name, ErrInvalidDate)
86		}
87		return nil
88	}
89	
90	// Register 登记一份档案。
91	//
92	// 编号重复或任一输入无效时明确失败，并且不写盘，已有记录不受影响。
93	func (s *Store) Register(in RegisterInput) error {
94		id, err := requireText(in.ID, "档案编号")
95		if err != nil {
96			return err
97		}
98		category, err := requireText(in.Category, "类别")
99		if err != nil {
100			return err
101		}
102		if err := requireDate(in.Start, "起算日"); err != nil {
103			return err
104		}
105		if err := requireDate(in.End, "保管截止日"); err != nil {
106			return err
107		}
108		if in.End.Before(in.Start) {
109			return fmt.Errorf("retention: 档案 %s 的保管截止日 %s 早于起算日 %s: %w",
110				id, in.End, in.Start, ErrRetentionEndBeforeStart)
111		}
112		return s.mutate(func(data *storeData) error {
113			if _, exists := data.Archives[id]; exists {
114				return fmt.Errorf("retention: 档案编号 %s 已登记: %w", id, ErrDuplicateID)
115			}
116			data.Archives[id] = &archiveRecord{
117				ID:         id,
118				Category:   category,
119				Start:      in.Start,
120				End:        in.End,
121				InitialEnd: in.End,
122				Freezes:    nil,
123			}
124			return nil
125		})
126	}
127	
128	// Freeze 为档案登记一条冻结。
129	//
130	// 冻结编号在同一档案内唯一。档案不存在、已销毁、冻结编号重复或输入无效时失败。
131	func (s *Store) Freeze(in FreezeInput) error {
132		archiveID, err := requireText(in.ArchiveID, "档案编号")
133		if err != nil {
134			return err
135		}
136		freezeID, err := requireText(in.FreezeID, "冻结编号")
137		if err != nil {
138			return err
139		}
140		reason, err := requireText(in.Reason, "冻结原因")
141		if err != nil {
142			return err
143		}
144		if err := requireDate(in.FrozenOn, "冻结日期"); err != nil {
145			return err
146		}
147		return s.mutate(func(data *storeData) error {
148			ar, ok := data.Archives[archiveID]
149			if !ok {
150				return fmt.Errorf("retention: 档案 %s 不存在，不能新增冻结: %w", archiveID, ErrNotFound)
151			}
152			if ar.Destroyed {
153				return fmt.Errorf("retention: 档案 %s 已销毁，不能新增冻结: %w", archiveID, ErrDestroyed)
154			}
155			for _, f := range ar.Freezes {
156				if f.ID == freezeID {
157					return fmt.Errorf("retention: 档案 %s 内冻结编号 %s 已存在: %w",
158						archiveID, freezeID, ErrDuplicateFreezeID)
159				}
160			}
161			ar.Freezes = append(ar.Freezes, &freezeRecord{
162				ID:       freezeID,
163				Reason:   reason,
164				FrozenOn: in.FrozenOn,
165			})
166			return nil
167		})
168	}
169	
170	// Release 解除一条冻结。
171	//
172	// 必须填写解除日期与原因，解除日期不能早于该冻结的冻结日期。
173	// 解除只在原记录上标记，不删除冻结记录，也不影响同一档案的其他冻结。
174	// 不能解除不存在或已经解除的冻结。
175	func (s *Store) Release(in ReleaseInput) error {
176		archiveID, err := requireText(in.ArchiveID, "档案编号")
177		if err != nil {
178			return err
179		}
180		freezeID, err := requireText(in.FreezeID, "冻结编号")
181		if err != nil {
182			return err
183		}
184		reason, err := requireText(in.Reason, "解除原因")
185		if err != nil {
186			return err
187		}
188		if err := requireDate(in.ReleasedOn, "解除日期"); err != nil {
189			return err
190		}
191		return s.mutate(func(data *storeData) error {
192			ar, ok := data.Archives[archiveID]
193			if !ok {
194				return fmt.Errorf("retention: 档案 %s 不存在: %w", archiveID, ErrNotFound)
195			}
196			var fr *freezeRecord
197			for _, f := range ar.Freezes {
198				if f.ID == freezeID {
199					fr = f
200					break
201				}
202			}
203			if fr == nil {
204				return fmt.Errorf("retention: 档案 %s 下冻结 %s 不存在: %w",
205					archiveID, freezeID, ErrFreezeNotFound)
206			}
207			if fr.Released {
208				return fmt.Errorf("retention: 档案 %s 的冻结 %s 已经解除，不能重复解除: %w",
209					archiveID, freezeID, ErrFreezeAlreadyReleased)
210			}
211			if in.ReleasedOn.Before(fr.FrozenOn) {
212				return fmt.Errorf("retention: 解除日期 %s 早于冻结 %s 的冻结日期 %s: %w",
213					in.ReleasedOn, freezeID, fr.FrozenOn, ErrReleaseBeforeFreeze)
214			}
215			fr.Released = true
216			fr.ReleaseReason = reason
217			releasedOn := in.ReleasedOn
218			fr.ReleasedOn = &releasedOn
219			return nil
220		})
221	}
222	
223	// Revise 修订一份尚未销毁档案的保管截止日，不必重新登记；
224	// 编号、类别、起算日不可改动。被冻结的档案也允许修订，但修订不解除冻结，
225	// 期限缩短后仍要满足原有冻结规则才能销毁。
226	//
227	// 首次办理时，所提交的原截止日必须与当前保存值相同，否则返回
228	// RetentionEndChangedError（errors.Is 可判定 ErrRetentionEndChanged），
229	// 其中带有当前截止日，不会覆盖他人的修改。成功后返回一条修订记录，
230	// 同时更新当前截止日；任何失败都不改变期限或留下修订历史。
231	//
232	// 修订编号在整个保管库内唯一，与销毁申请编号互不占用。同编号且提交内容
233	// 完全相同的重试只返回第一次成功的记录，不增加历史——即使后来再次改过
234	// 期限或档案已经销毁；沿用成功编号改变任何一项内容则返回编号冲突。
235	// 失败过的编号仍可用于重新提交。
236	func (s *Store) Revise(in ReviseInput) (RevisionRecord, error) {
237		revisionID, err := requireText(in.RevisionID, "修订编号")
238		if err != nil {
239			return RevisionRecord{}, err
240		}
241		archiveID, err := requireText(in.ArchiveID, "档案编号")
242		if err != nil {
243			return RevisionRecord{}, err
244		}
245		reason, err := requireText(in.Reason, "修订原因")
246		if err != nil {
247			return RevisionRecord{}, err
248		}
249		if err := requireDate(in.OriginalEnd, "原截止日"); err != nil {
250			return RevisionRecord{}, err
251		}
252		if err := requireDate(in.NewEnd, "新截止日"); err != nil {
253			return RevisionRecord{}, err
254		}
255		if err := requireDate(in.RevisedOn, "修订日期"); err != nil {
256			return RevisionRecord{}, err
257		}
258		if in.NewEnd.Equal(in.OriginalEnd) {
259			return RevisionRecord{}, fmt.Errorf("retention: 档案 %s 的新截止日 %s 与原截止日相同: %w",
260				archiveID, in.NewEnd, ErrRevisionEndUnchanged)
261		}
262	
263		var result RevisionRecord
264		err = s.mutate(func(data *storeData) error {
265			// 修订编号与销毁申请编号互不占用。
266			if _, ok := data.Manifests[revisionID]; ok {
267				return fmt.Errorf("retention: 修订编号 %s 已用作销毁申请编号: %w",
268					revisionID, ErrRevisionConflict)
269			}
270			// 同编号重试：内容完全相同则取回第一次成功的记录（即使期限后来
271			// 再次改动或档案已销毁）；改变任何一项内容即编号冲突。
272			if owner, rec := findRevision(data, revisionID); rec != nil {
273				if sameRevision(owner, rec, archiveID, in, reason) {
274					result = revisionFromRecord(archiveID, rec)
275					return nil
276				}
277				return fmt.Errorf("retention: 修订编号 %s 已成功使用，本次内容与原修订不一致: %w",
278					revisionID, ErrRevisionConflict)
279			}
280	
281			ar, ok := data.Archives[archiveID]
282			if !ok {
283				return fmt.Errorf("retention: 档案 %s 不存在，不能修订截止日: %w", archiveID, ErrNotFound)
284			}
285			if ar.Destroyed {
286				return fmt.Errorf("retention: 档案 %s 已销毁，不能修订截止日: %w", archiveID, ErrDestroyed)
287			}
288			if in.NewEnd.Before(ar.Start) {
289				return fmt.Errorf("retention: 档案 %s 的新截止日 %s 早于起算日 %s: %w",
290					archiveID, in.NewEnd, ar.Start, ErrRetentionEndBeforeStart)
291			}
292			// 排他锁内比较并更新：两个程序同时修订同一截止日，只有先成功者生效。
293			if !ar.End.Equal(in.OriginalEnd) {
294				return &RetentionEndChangedError{ArchiveID: archiveID, CurrentEnd: ar.End}
295			}
296			rec := &revisionRecord{
297				ID:        revisionID,
298				OldEnd:    ar.End,
299				NewEnd:    in.NewEnd,
300				RevisedOn: in.RevisedOn,
301				Reason:    reason,
302			}
303			ar.Revisions = append(ar.Revisions, rec)
304			ar.End = in.NewEnd
305			result = revisionFromRecord(archiveID, rec)
306			return nil
307		})
308		if err != nil {
309			return RevisionRecord{}, err
310		}
311		return result, nil
312	}
313	
314	// findRevision 在整个保管库内按修订编号查找已成功的修订，
315	// 返回所属档案与修订记录；不存在时返回 nil, nil。
316	func findRevision(data *storeData, revisionID string) (*archiveRecord, *revisionRecord) {
317		for _, ar := range data.Archives {
318			for _, rec := range ar.Revisions {
319				if rec.ID == revisionID {
320					return ar, rec
321				}
322			}
323		}
324		return nil, nil
325	}
326	
327	// sameRevision 判断本次提交与已成功的修订内容是否完全一致。
328	// 文本比较以去除首尾空白后的值为准（archiveID 与 reason 须已规范化）。
329	func sameRevision(owner *archiveRecord, rec *revisionRecord, archiveID string, in ReviseInput, reason string) bool {
330		return owner.ID == archiveID &&
331			rec.OldEnd.Equal(in.OriginalEnd) &&
332			rec.NewEnd.Equal(in.NewEnd) &&
333			rec.RevisedOn.Equal(in.RevisedOn) &&
334			rec.Reason == reason
335	}
336	
337	func revisionFromRecord(archiveID string, rec *revisionRecord) RevisionRecord {
338		return RevisionRecord{
339			RevisionID: rec.ID,
340			ArchiveID:  archiveID,
341			OldEnd:     rec.OldEnd,
342			NewEnd:     rec.NewEnd,
343			RevisedOn:  rec.RevisedOn,
344			Reason:     rec.Reason,
345		}
346	}
347	
348	// Destroy 办理一次销毁申请。
349	//
350	// 只有名单中全部档案都存在、按处理日期已到期（处理日期不早于截止日，
351	// 截止日当天即到期）、未销毁且没有未解除冻结时，才会同时完成销毁，
352	// 并生成一份内容此后不可更改的已关闭清册。
353	//
354	// 名单为空、名单内编号重复或任一档案不符合条件时，整次申请失败，
355	// 不会留下部分销毁或清册。
356	//
357	// 同一申请编号此前已经成功办理时：处理日期与档案集合完全相同（顺序无关）
358	// 则返回原清册；沿用编号但改变日期或档案集合则失败。失败过的申请
359	// 在条件改变后可以用同一编号再次提交。
360	func (s *Store) Destroy(req DestructionRequest) (Manifest, error) {
361		applicationID, ids, seen, err := validateBatchInputs(req.ApplicationID, req.ProcessedOn, req.ArchiveIDs)
362		if err != nil {
363			return Manifest{}, err
364		}
365	
366		var result Manifest
367		err = s.mutate(func(data *storeData) error {
368			// 已成功的申请编号：幂等返回原清册，或因内容不一致失败。
369			if existing, ok := data.Manifests[applicationID]; ok {
370				if !sameApplication(existing, req.ProcessedOn, seen) {
371					return fmt.Errorf("retention: 申请编号 %s 已成功使用，本次日期或档案集合与原申请不一致: %w",
372						applicationID, ErrApplicationMismatch)
373				}
374				result = manifestFromRecord(existing)
375				return nil
376			}
377			// 销毁申请编号与修订编号互不占用。
378			if _, rec := findRevision(data, applicationID); rec != nil {
379				return fmt.Errorf("retention: 申请编号 %s 已用作修订编号: %w",
380					applicationID, ErrRevisionConflict)
381			}
382	
383			// 逐份校验，任一不符合条件则整体放弃（此时尚未改动任何记录）。
384			// 判断规则与只读核对共用 evaluateArchive：按提交顺序检查，
385			// 在第一份不能办理的档案处失败，同一档案的多个问题按固定先后取其首条。
386			for _, id := range ids {
387				r := evaluateArchive(data, id, req.ProcessedOn)
388				if len(r.Obstructions) > 0 {
389					return firstObstructionError(r, req.ProcessedOn)
390				}
391			}
392	
393			// 全部满足：生成关闭清册，内容为各档案当时登记内容的快照。
394			processedOn := req.ProcessedOn
395			rec := &manifestRecord{
396				ApplicationID: applicationID,
397				ProcessedOn:   &processedOn,
398			}
399			ordered := append([]string(nil), ids...)
400			sort.Strings(ordered)
401			for _, id := range ordered {
402				ar := data.Archives[id]
403				rec.Entries = append(rec.Entries, manifestEntry{
404					ID:       ar.ID,
405					Category: ar.Category,
406					Start:    ar.Start,
407					End:      ar.End,
408				})
409				ar.Destroyed = true
410				ar.ManifestID = applicationID
411			}
412			data.Manifests[applicationID] = rec
413			result = manifestFromRecord(rec)
414			return nil
415		})
416		if err != nil {
417			return Manifest{}, err
418		}
419		return result, nil
420	}
421	
422	// sameApplication 判断已成功申请与本次提交的处理日期和档案集合是否完全一致（顺序无关）。
423	// 调用前记录已通过 load 的语义校验，处理日期必然存在且有效。
424	func sameApplication(existing *manifestRecord, processedOn Date, idSet map[string]struct{}) bool {
425		if existing.ProcessedOn == nil || !existing.ProcessedOn.Equal(processedOn) {
426			return false
427		}
428		if len(existing.Entries) != len(idSet) {
429			return false
430		}
431		for _, e := range existing.Entries {
432			if _, ok := idSet[e.ID]; !ok {
433				return false
434			}
435		}
436		return true
437	}
438	
439	func manifestFromRecord(rec *manifestRecord) Manifest {
440		m := Manifest{
441			ApplicationID: rec.ApplicationID,
442			Entries:       make([]ManifestEntry, 0, len(rec.Entries)),
443		}
444		// 通过校验的已关闭清册必然带有有效处理日期；防御性保留零值兜底。
445		if rec.ProcessedOn != nil {
446			m.ProcessedOn = *rec.ProcessedOn
447		}
448		for _, e := range rec.Entries {
449			m.Entries = append(m.Entries, ManifestEntry{
450				ID:       e.ID,
451				Category: e.Category,
452				Start:    e.Start,
453				End:      e.End,
454			})
455		}
456		return m
457	}
458	
459	func freezeFromRecord(fr *freezeRecord) FreezeRecord {
460		out := FreezeRecord{
461			ID:            fr.ID,
462			Reason:        fr.Reason,
463			FrozenOn:      fr.FrozenOn,
464			Released:      fr.Released,
465			ReleaseReason: fr.ReleaseReason,
466		}
467		if fr.ReleasedOn != nil {
468			out.ReleasedOn = *fr.ReleasedOn
469		}
470		return out
471	}
472	
473	// History 按档案编号核对完整历史。
474	//
475	// 结果包含登记内容、最初与当前保管截止日、按成功顺序排列的全部修订记录、
476	// 全部冻结及解除历史、当前未解除冻结、销毁状态以及对应的已关闭清册。档案未登记时 found 为 false（err 为 nil），
477	// 这是明确的不存在结果。
478	func (s *Store) History(archiveID string) (h ArchiveHistory, found bool, err error) {
479		id := normalizeText(archiveID)
480		if id == "" {
481			return ArchiveHistory{}, false, fmt.Errorf("retention: 档案编号不能为空白: %w", ErrBlankField)
482		}
483		err = s.view(func(data *storeData) error {
484			ar, ok := data.Archives[id]
485			if !ok {
486				return nil
487			}
488			found = true
489			h = ArchiveHistory{
490				ID:                    ar.ID,
491				Category:              ar.Category,
492				Start:                 ar.Start,
493				InitialEnd:            ar.InitialEnd,
494				RetentionEnd:          ar.End,
495				Destroyed:             ar.Destroyed,
496				ManifestApplicationID: ar.ManifestID,
497				Revisions:             make([]RevisionRecord, 0, len(ar.Revisions)),
498				Freezes:               make([]FreezeRecord, 0, len(ar.Freezes)),
499			}
500			for _, rec := range ar.Revisions {
501				h.Revisions = append(h.Revisions, revisionFromRecord(ar.ID, rec))
502			}
503			for _, fr := range ar.Freezes {
504				view := freezeFromRecord(fr)
505				h.Freezes = append(h.Freezes, view)
506				if !fr.Released {
507					h.ActiveFreezes = append(h.ActiveFreezes, view)
508				}
509			}
510			if ar.Destroyed && ar.ManifestID != "" {
511				if rec, ok := data.Manifests[ar.ManifestID]; ok {
512					m := manifestFromRecord(rec)
513					h.Manifest = &m
514				}
515			}
516			return nil
517		})
518		if err != nil {
519			return ArchiveHistory{}, false, err
520		}
521		return h, found, nil
522	}
523	
524	// Manifest 按申请编号查询一份已关闭清册。不存在时 found 为 false。
525	func (s *Store) GetManifest(applicationID string) (m Manifest, found bool, err error) {
526		id := normalizeText(applicationID)
527		if id == "" {
528			return Manifest{}, false, fmt.Errorf("retention: 申请编号不能为空白: %w", ErrBlankField)
529		}
530		err = s.view(func(data *storeData) error {
531			if rec, ok := data.Manifests[id]; ok {
532				m = manifestFromRecord(rec)
533				found = true
534			}
535			return nil
536		})
537		if err != nil {
538			return Manifest{}, false, err
539		}
540		return m, found, nil
541	}
542

file.content:
package retention

import (
	"fmt"
	"sort"
	"strings"
)

// RegisterInput 是登记一份档案所需的信息。
//
// 编号和类别不能是空白；日期必须是 ParseDate 能解析的真实日期；
// 截止日可以与起算日相同，但不能更早。
type RegisterInput struct {
	ID       string
	Category string
	Start    Date
	End      Date
}

// FreezeInput 是为档案新增一条冻结所需的信息。
type FreezeInput struct {
	ArchiveID string
	FreezeID  string
	Reason    string
	FrozenOn  Date
}

// ReleaseInput 是解除一条冻结所需的信息。
type ReleaseInput struct {
	ArchiveID  string
	FreezeID   string
	Reason     string
	ReleasedOn Date
}

// ReviseInput 是一次保管截止日修订所需的信息。
//
// 修订编号在整个保管库内唯一，且与销毁申请编号互不占用；
// OriginalEnd 是调用者看到的当前截止日，用于发现他人已改动期限；
// NewEnd 不能早于起算日，也不能等于所提交的原截止日；
// RevisedOn 仅用于记录，提交成功即采用新期限。
// 编号与原因去除首尾空白后不得为空白，文本比较以去空白后的值为准。
type ReviseInput struct {
	RevisionID  string
	ArchiveID   string
	OriginalEnd Date
	NewEnd      Date
	RevisedOn   Date
	Reason      string
}

// DestructionRequest 是一次销毁申请。
//
// 一次申请可以选择多个档案。申请编号在所有成功申请中唯一，
// 处理日期即判断档案是否到期所依据的日期。
type DestructionRequest struct {
	ApplicationID string
	ProcessedOn   Date
	ArchiveIDs    []string
}

// CheckRequest 是销毁前一次只做核对的请求，字段含义与 DestructionRequest 相同。
//
// 核对不销毁任何档案、不生成或改写清册，也不占用申请编号：
// 核对失败或发现阻碍后，仍可沿用同一编号继续核对或正式提交。
type CheckRequest struct {
	ApplicationID string
	ProcessedOn   Date
	ArchiveIDs    []string
}

// normalizeText 去除首尾空白；空白字段统一按空白处理，避免同值异写。
func normalizeText(s string) string { return strings.TrimSpace(s) }

func requireText(value, name string) (string, error) {
	v := normalizeText(value)
	if v == "" {
		return "", fmt.Errorf("retention: %s不能为空白: %w", name, ErrBlankField)
	}
	return v, nil
}

func requireDate(d Date, name string) error {
	if d.IsZero() {
		return fmt.Errorf("retention: %s缺失或无效，应为 YYYY-MM-DD: %w", name, ErrInvalidDate)
	}
	return nil
}

// Register 登记一份档案。
//
// 编号重复或任一输入无效时明确失败，并且不写盘，已有记录不受影响。
func (s *Store) Register(in RegisterInput) error {
	id, err := requireText(in.ID, "档案编号")
	if err != nil {
		return err
	}
	category, err := requireText(in.Category, "类别")
	if err != nil {
		return err
	}
	if err := requireDate(in.Start, "起算日"); err != nil {
		return err
	}
	if err := requireDate(in.End, "保管截止日"); err != nil {
		return err
	}
	if in.End.Before(in.Start) {
		return fmt.Errorf("retention: 档案 %s 的保管截止日 %s 早于起算日 %s: %w",
			id, in.End, in.Start, ErrRetentionEndBeforeStart)
	}
	return s.mutate(func(data *storeData) error {
		if _, exists := data.Archives[id]; exists {
			return fmt.Errorf("retention: 档案编号 %s 已登记: %w", id, ErrDuplicateID)
		}
		data.Archives[id] = &archiveRecord{
			ID:         id,
			Category:   category,
			Start:      in.Start,
			End:        in.End,
			InitialEnd: in.End,
			Freezes:    nil,
		}
		return nil
	})
}

// Freeze 为档案登记一条冻结。
//
// 冻结编号在同一档案内唯一。档案不存在、已销毁、冻结编号重复或输入无效时失败。
func (s *Store) Freeze(in FreezeInput) error {
	archiveID, err := requireText(in.ArchiveID, "档案编号")
	if err != nil {
		return err
	}
	freezeID, err := requireText(in.FreezeID, "冻结编号")
	if err != nil {
		return err
	}
	reason, err := requireText(in.Reason, "冻结原因")
	if err != nil {
		return err
	}
	if err := requireDate(in.FrozenOn, "冻结日期"); err != nil {
		return err
	}
	return s.mutate(func(data *storeData) error {
		ar, ok := data.Archives[archiveID]
		if !ok {
			return fmt.Errorf("retention: 档案 %s 不存在，不能新增冻结: %w", archiveID, ErrNotFound)
		}
		if ar.Destroyed {
			return fmt.Errorf("retention: 档案 %s 已销毁，不能新增冻结: %w", archiveID, ErrDestroyed)
		}
		for _, f := range ar.Freezes {
			if f.ID == freezeID {
				return fmt.Errorf("retention: 档案 %s 内冻结编号 %s 已存在: %w",
					archiveID, freezeID, ErrDuplicateFreezeID)
			}
		}
		ar.Freezes = append(ar.Freezes, &freezeRecord{
			ID:       freezeID,
			Reason:   reason,
			FrozenOn: in.FrozenOn,
		})
		return nil
	})
}

// Release 解除一条冻结。
//
// 必须填写解除日期与原因，解除日期不能早于该冻结的冻结日期。
// 解除只在原记录上标记，不删除冻结记录，也不影响同一档案的其他冻结。
// 不能解除不存在或已经解除的冻结。
func (s *Store) Release(in ReleaseInput) error {
	archiveID, err := requireText(in.ArchiveID, "档案编号")
	if err != nil {
		return err
	}
	freezeID, err := requireText(in.FreezeID, "冻结编号")
	if err != nil {
		return err
	}
	reason, err := requireText(in.Reason, "解除原因")
	if err != nil {
		return err
	}
	if err := requireDate(in.ReleasedOn, "解除日期"); err != nil {
		return err
	}
	return s.mutate(func(data *storeData) error {
		ar, ok := data.Archives[archiveID]
		if !ok {
			return fmt.Errorf("retention: 档案 %s 不存在: %w", archiveID, ErrNotFound)
		}
		var fr *freezeRecord
		for _, f := range ar.Freezes {
			if f.ID == freezeID {
				fr = f
				break
			}
		}
		if fr == nil {
			return fmt.Errorf("retention: 档案 %s 下冻结 %s 不存在: %w",
				archiveID, freezeID, ErrFreezeNotFound)
		}
		if fr.Released {
			return fmt.Errorf("retention: 档案 %s 的冻结 %s 已经解除，不能重复解除: %w",
				archiveID, freezeID, ErrFreezeAlreadyReleased)
		}
		if in.ReleasedOn.Before(fr.FrozenOn) {
			return fmt.Errorf("retention: 解除日期 %s 早于冻结 %s 的冻结日期 %s: %w",
				in.ReleasedOn, freezeID, fr.FrozenOn, ErrReleaseBeforeFreeze)
		}
		fr.Released = true
		fr.ReleaseReason = reason
		releasedOn := in.ReleasedOn
		fr.ReleasedOn = &releasedOn
		return nil
	})
}

// Revise 修订一份尚未销毁档案的保管截止日，不必重新登记；
// 编号、类别、起算日不可改动。被冻结的档案也允许修订，但修订不解除冻结，
// 期限缩短后仍要满足原有冻结规则才能销毁。
//
// 首次办理时，所提交的原截止日必须与当前保存值相同，否则返回
// RetentionEndChangedError（errors.Is 可判定 ErrRetentionEndChanged），
// 其中带有当前截止日，不会覆盖他人的修改。成功后返回一条修订记录，
// 同时更新当前截止日；任何失败都不改变期限或留下修订历史。
//
// 修订编号在整个保管库内唯一，与销毁申请编号互不占用。同编号且提交内容
// 完全相同的重试只返回第一次成功的记录，不增加历史——即使后来再次改过
// 期限或档案已经销毁；沿用成功编号改变任何一项内容则返回编号冲突。
// 失败过的编号仍可用于重新提交。
func (s *Store) Revise(in ReviseInput) (RevisionRecord, error) {
	revisionID, err := requireText(in.RevisionID, "修订编号")
	if err != nil {
		return RevisionRecord{}, err
	}
	archiveID, err := requireText(in.ArchiveID, "档案编号")
	if err != nil {
		return RevisionRecord{}, err
	}
	reason, err := requireText(in.Reason, "修订原因")
	if err != nil {
		return RevisionRecord{}, err
	}
	if err := requireDate(in.OriginalEnd, "原截止日"); err != nil {
		return RevisionRecord{}, err
	}
	if err := requireDate(in.NewEnd, "新截止日"); err != nil {
		return RevisionRecord{}, err
	}
	if err := requireDate(in.RevisedOn, "修订日期"); err != nil {
		return RevisionRecord{}, err
	}
	if in.NewEnd.Equal(in.OriginalEnd) {
		return RevisionRecord{}, fmt.Errorf("retention: 档案 %s 的新截止日 %s 与原截止日相同: %w",
			archiveID, in.NewEnd, ErrRevisionEndUnchanged)
	}

	var result RevisionRecord
	err = s.mutate(func(data *storeData) error {
		// 修订编号与销毁申请编号互不占用。
		if _, ok := data.Manifests[revisionID]; ok {
			return fmt.Errorf("retention: 修订编号 %s 已用作销毁申请编号: %w",
				revisionID, ErrRevisionConflict)
		}
		// 同编号重试：内容完全相同则取回第一次成功的记录（即使期限后来
		// 再次改动或档案已销毁）；改变任何一项内容即编号冲突。
		if owner, rec := findRevision(data, revisionID); rec != nil {
			if sameRevision(owner, rec, archiveID, in, reason) {
				result = revisionFromRecord(archiveID, rec)
				return nil
			}
			return fmt.Errorf("retention: 修订编号 %s 已成功使用，本次内容与原修订不一致: %w",
				revisionID, ErrRevisionConflict)
		}

		ar, ok := data.Archives[archiveID]
		if !ok {
			return fmt.Errorf("retention: 档案 %s 不存在，不能修订截止日: %w", archiveID, ErrNotFound)
		}
		if ar.Destroyed {
			return fmt.Errorf("retention: 档案 %s 已销毁，不能修订截止日: %w", archiveID, ErrDestroyed)
		}
		if in.NewEnd.Before(ar.Start) {
			return fmt.Errorf("retention: 档案 %s 的新截止日 %s 早于起算日 %s: %w",
				archiveID, in.NewEnd, ar.Start, ErrRetentionEndBeforeStart)
		}
		// 排他锁内比较并更新：两个程序同时修订同一截止日，只有先成功者生效。
		if !ar.End.Equal(in.OriginalEnd) {
			return &RetentionEndChangedError{ArchiveID: archiveID, CurrentEnd: ar.End}
		}
		rec := &revisionRecord{
			ID:        revisionID,
			OldEnd:    ar.End,
			NewEnd:    in.NewEnd,
			RevisedOn: in.RevisedOn,
			Reason:    reason,
		}
		ar.Revisions = append(ar.Revisions, rec)
		ar.End = in.NewEnd
		result = revisionFromRecord(archiveID, rec)
		return nil
	})
	if err != nil {
		return RevisionRecord{}, err
	}
	return result, nil
}

// findRevision 在整个保管库内按修订编号查找已成功的修订，
// 返回所属档案与修订记录；不存在时返回 nil, nil。
func findRevision(data *storeData, revisionID string) (*archiveRecord, *revisionRecord) {
	for _, ar := range data.Archives {
		for _, rec := range ar.Revisions {
			if rec.ID == revisionID {
				return ar, rec
			}
		}
	}
	return nil, nil
}

// sameRevision 判断本次提交与已成功的修订内容是否完全一致。
// 文本比较以去除首尾空白后的值为准（archiveID 与 reason 须已规范化）。
func sameRevision(owner *archiveRecord, rec *revisionRecord, archiveID string, in ReviseInput, reason string) bool {
	return owner.ID == archiveID &&
		rec.OldEnd.Equal(in.OriginalEnd) &&
		rec.NewEnd.Equal(in.NewEnd) &&
		rec.RevisedOn.Equal(in.RevisedOn) &&
		rec.Reason == reason
}

func revisionFromRecord(archiveID string, rec *revisionRecord) RevisionRecord {
	return RevisionRecord{
		RevisionID: rec.ID,
		ArchiveID:  archiveID,
		OldEnd:     rec.OldEnd,
		NewEnd:     rec.NewEnd,
		RevisedOn:  rec.RevisedOn,
		Reason:     rec.Reason,
	}
}

// Destroy 办理一次销毁申请。
//
// 只有名单中全部档案都存在、按处理日期已到期（处理日期不早于截止日，
// 截止日当天即到期）、未销毁且没有未解除冻结时，才会同时完成销毁，
// 并生成一份内容此后不可更改的已关闭清册。
//
// 名单为空、名单内编号重复或任一档案不符合条件时，整次申请失败，
// 不会留下部分销毁或清册。
//
// 同一申请编号此前已经成功办理时：处理日期与档案集合完全相同（顺序无关）
// 则返回原清册；沿用编号但改变日期或档案集合则失败。失败过的申请
// 在条件改变后可以用同一编号再次提交。
func (s *Store) Destroy(req DestructionRequest) (Manifest, error) {
	applicationID, ids, seen, err := validateBatchInputs(req.ApplicationID, req.ProcessedOn, req.ArchiveIDs)
	if err != nil {
		return Manifest{}, err
	}

	var result Manifest
	err = s.mutate(func(data *storeData) error {
		// 已成功的申请编号：幂等返回原清册，或因内容不一致失败。
		if existing, ok := data.Manifests[applicationID]; ok {
			if !sameApplication(existing, req.ProcessedOn, seen) {
				return fmt.Errorf("retention: 申请编号 %s 已成功使用，本次日期或档案集合与原申请不一致: %w",
					applicationID, ErrApplicationMismatch)
			}
			result = manifestFromRecord(existing)
			return nil
		}
		// 销毁申请编号与修订编号互不占用。
		if _, rec := findRevision(data, applicationID); rec != nil {
			return fmt.Errorf("retention: 申请编号 %s 已用作修订编号: %w",
				applicationID, ErrRevisionConflict)
		}

		// 逐份校验，任一不符合条件则整体放弃（此时尚未改动任何记录）。
		// 判断规则与只读核对共用 evaluateArchive：按提交顺序检查，
		// 在第一份不能办理的档案处失败，同一档案的多个问题按固定先后取其首条。
		for _, id := range ids {
			r := evaluateArchive(data, id, req.ProcessedOn)
			if len(r.Obstructions) > 0 {
				return firstObstructionError(r, req.ProcessedOn)
			}
		}

		// 全部满足：生成关闭清册，内容为各档案当时登记内容的快照。
		processedOn := req.ProcessedOn
		rec := &manifestRecord{
			ApplicationID: applicationID,
			ProcessedOn:   &processedOn,
		}
		ordered := append([]string(nil), ids...)
		sort.Strings(ordered)
		for _, id := range ordered {
			ar := data.Archives[id]
			rec.Entries = append(rec.Entries, manifestEntry{
				ID:       ar.ID,
				Category: ar.Category,
				Start:    ar.Start,
				End:      ar.End,
			})
			ar.Destroyed = true
			ar.ManifestID = applicationID
		}
		data.Manifests[applicationID] = rec
		result = manifestFromRecord(rec)
		return nil
	})
	if err != nil {
		return Manifest{}, err
	}
	return result, nil
}

// sameApplication 判断已成功申请与本次提交的处理日期和档案集合是否完全一致（顺序无关）。
// 调用前记录已通过 load 的语义校验，处理日期必然存在且有效。
func sameApplication(existing *manifestRecord, processedOn Date, idSet map[string]struct{}) bool {
	if existing.ProcessedOn == nil || !existing.ProcessedOn.Equal(processedOn) {
		return false
	}
	if len(existing.Entries) != len(idSet) {
		return false
	}
	for _, e := range existing.Entries {
		if _, ok := idSet[e.ID]; !ok {
			return false
		}
	}
	return true
}

func manifestFromRecord(rec *manifestRecord) Manifest {
	m := Manifest{
		ApplicationID: rec.ApplicationID,
		Entries:       make([]ManifestEntry, 0, len(rec.Entries)),
	}
	// 通过校验的已关闭清册必然带有有效处理日期；防御性保留零值兜底。
	if rec.ProcessedOn != nil {
		m.ProcessedOn = *rec.ProcessedOn
	}
	for _, e := range rec.Entries {
		m.Entries = append(m.Entries, ManifestEntry{
			ID:       e.ID,
			Category: e.Category,
			Start:    e.Start,
			End:      e.End,
		})
	}
	return m
}

func freezeFromRecord(fr *freezeRecord) FreezeRecord {
	out := FreezeRecord{
		ID:            fr.ID,
		Reason:        fr.Reason,
		FrozenOn:      fr.FrozenOn,
		Released:      fr.Released,
		ReleaseReason: fr.ReleaseReason,
	}
	if fr.ReleasedOn != nil {
		out.ReleasedOn = *fr.ReleasedOn
	}
	return out
}

// History 按档案编号核对完整历史。
//
// 结果包含登记内容、最初与当前保管截止日、按成功顺序排列的全部修订记录、
// 全部冻结及解除历史、当前未解除冻结、销毁状态以及对应的已关闭清册。档案未登记时 found 为 false（err 为 nil），
// 这是明确的不存在结果。
func (s *Store) History(archiveID string) (h ArchiveHistory, found bool, err error) {
	id := normalizeText(archiveID)
	if id == "" {
		return ArchiveHistory{}, false, fmt.Errorf("retention: 档案编号不能为空白: %w", ErrBlankField)
	}
	err = s.view(func(data *storeData) error {
		ar, ok := data.Archives[id]
		if !ok {
			return nil
		}
		found = true
		h = ArchiveHistory{
			ID:                    ar.ID,
			Category:              ar.Category,
			Start:                 ar.Start,
			InitialEnd:            ar.InitialEnd,
			RetentionEnd:          ar.End,
			Destroyed:             ar.Destroyed,
			ManifestApplicationID: ar.ManifestID,
			Revisions:             make([]RevisionRecord, 0, len(ar.Revisions)),
			Freezes:               make([]FreezeRecord, 0, len(ar.Freezes)),
		}
		for _, rec := range ar.Revisions {
			h.Revisions = append(h.Revisions, revisionFromRecord(ar.ID, rec))
		}
		for _, fr := range ar.Freezes {
			view := freezeFromRecord(fr)
			h.Freezes = append(h.Freezes, view)
			if !fr.Released {
				h.ActiveFreezes = append(h.ActiveFreezes, view)
			}
		}
		if ar.Destroyed && ar.ManifestID != "" {
			if rec, ok := data.Manifests[ar.ManifestID]; ok {
				m := manifestFromRecord(rec)
				h.Manifest = &m
			}
		}
		return nil
	})
	if err != nil {
		return ArchiveHistory{}, false, err
	}
	return h, found, nil
}

// Manifest 按申请编号查询一份已关闭清册。不存在时 found 为 false。
func (s *Store) GetManifest(applicationID string) (m Manifest, found bool, err error) {
	id := normalizeText(applicationID)
	if id == "" {
		return Manifest{}, false, fmt.Errorf("retention: 申请编号不能为空白: %w", ErrBlankField)
	}
	err = s.view(func(data *storeData) error {
		if rec, ok := data.Manifests[id]; ok {
			m = manifestFromRecord(rec)
			found = true
		}
		return nil
	})
	if err != nil {
		return Manifest{}, false, err
	}
	return m, found, nil
}

package retention

import (
	"errors"
	"fmt"
)

// 业务规则错误。调用方可用 errors.Is 判断失败类别，具体错误信息会附带上编号等上下文。
var (
	// ErrNotFound 表示档案或相关记录不存在。
	ErrNotFound = errors.New("retention: 档案不存在")
	// ErrDuplicateID 表示档案编号已经登记过。
	ErrDuplicateID = errors.New("retention: 档案编号重复")
	// ErrDestroyed 表示档案已经销毁，不能再执行该操作。
	ErrDestroyed = errors.New("retention: 档案已销毁")
	// ErrBlankField 表示必填的编号、类别或原因为空白。
	ErrBlankField = errors.New("retention: 字段不能为空白")
	// ErrInvalidDate 表示日期缺失或不是真实的日历日期。
	ErrInvalidDate = errors.New("retention: 日期无效")
	// ErrRetentionEndBeforeStart 表示保管截止日早于起算日。
	ErrRetentionEndBeforeStart = errors.New("retention: 保管截止日不能早于起算日")
	// ErrReleaseBeforeFreeze 表示解除日期早于冻结日期。
	ErrReleaseBeforeFreeze = errors.New("retention: 解除日期不能早于冻结日期")
	// ErrDuplicateFreezeID 表示同一档案内冻结编号重复。
	ErrDuplicateFreezeID = errors.New("retention: 冻结编号在同一档案内重复")
	// ErrFreezeNotFound 表示该档案下没有对应编号的冻结。
	ErrFreezeNotFound = errors.New("retention: 冻结不存在")
	// ErrFreezeAlreadyReleased 表示冻结已经解除，不能重复解除。
	ErrFreezeAlreadyReleased = errors.New("retention: 冻结已经解除")
	// ErrEmptyDestructionList 表示销毁名单为空。
	ErrEmptyDestructionList = errors.New("retention: 销毁名单不能为空")
	// ErrDuplicateSelection 表示同一次销毁申请中档案编号重复。
	ErrDuplicateSelection = errors.New("retention: 销毁名单中档案编号重复")
	// ErrNotDestroyable 表示名单中存在未到期或仍有未解除冻结的档案。
	ErrNotDestroyable = errors.New("retention: 存在不能销毁的档案")
	// ErrNotExpired 表示档案尚未到保管截止日。截止日当天才视为到期。
	ErrNotExpired = errors.New("retention: 档案尚未到期")
	// ErrActiveFreeze 表示档案仍有未解除的冻结。
	ErrActiveFreeze = errors.New("retention: 档案存在未解除的冻结")
	// ErrApplicationMismatch 表示申请编号已成功使用，但本次日期或档案集合与原申请不一致。
	ErrApplicationMismatch = errors.New("retention: 申请编号与已成功的申请不一致")
	// ErrArchiveAlreadyOnManifest 表示档案已经出现在另一份成功清册中。
	ErrArchiveAlreadyOnManifest = errors.New("retention: 档案已在其他销毁清册中")
	// ErrRetentionEndChanged 表示提交的原截止日与当前保存值不一致，期限已被他人改动。
	ErrRetentionEndChanged = errors.New("retention: 保管截止日已变化")
	// ErrRevisionConflict 表示修订编号已成功使用但本次内容不同，或与销毁申请编号相互占用。
	ErrRevisionConflict = errors.New("retention: 修订编号冲突")
	// ErrRevisionEndUnchanged 表示新截止日与所提交的原截止日相同。
	ErrRevisionEndUnchanged = errors.New("retention: 新截止日不能等于原截止日")
	// ErrCorruptState 表示状态文件已存在但内容损坏，无法读取已保存的记录。
	// 与“尚未建立记录”（状态文件不存在，按空库打开）明确区分：
	// 出现该错误时打开、查询与办理都会失败，且原文件保持原样。
	ErrCorruptState = errors.New("retention: 无法读取已保存的记录，状态文件已损坏")
)

// RetentionEndChangedError 表示修订提交的原截止日与当前保存值不一致：
// 首次办理时期限已被他人改动，本次修订未生效。CurrentEnd 给出当前保存的截止日。
type RetentionEndChangedError struct {
	ArchiveID  string
	CurrentEnd Date
}

func (e *RetentionEndChangedError) Error() string {
	return fmt.Sprintf("retention: 档案 %s 的保管截止日已变化，当前为 %s: %s",
		e.ArchiveID, e.CurrentEnd, ErrRetentionEndChanged)
}

// Is 支持 errors.Is(err, ErrRetentionEndChanged)。
func (e *RetentionEndChangedError) Is(target error) bool { return target == ErrRetentionEndChanged }

// InvalidDateError 说明 ParseDate 收到的值不是合法的 YYYY-MM-DD 真实日期。
type InvalidDateError struct {
	Value string
}

func (e *InvalidDateError) Error() string {
	return "retention: 日期无效，应为 YYYY-MM-DD 且真实存在: " + e.Value
}

// Is 支持 errors.Is(err, ErrInvalidDate)。
func (e *InvalidDateError) Is(target error) bool { return target == ErrInvalidDate }

