		"查找编号与记录 id 不同": {
			state(`"A-1"`, archive(`"id":"A-2"`)),
			[]string{"不一致", "A-1", "A-2"},
		},
		"id 仅大小写不同": {
			state(`"A-1"`, archive(`"id":"a-1"`)),
			[]string{"不一致", "A-1", "a-1"},
		},
		"id 尾部多空白": {
			state(`"A-1"`, archive(`"id":"A-1 "`)),
			[]string{"不一致", "A-1"},
		},
		"id 首部多空白": {
			state(`"A-1"`, archive(`"id":" A-1"`)),
			[]string{"不一致", "A-1"},
		},
