		},
		"id 为空串": {
			state(`"A-1"`, archive(`"id":""`)),
			[]string{"A-1", "缺少有效的 id"},
		},
		"id 只有空白": {
			state(`"A-1"`, archive(`"id":"  \t "`)),
			[]string{"A-1", "缺少有效的 id"},
		},
		"查找编号为空串": {
			state(`""`, archive(`"id":""`)),
			[]string{"空白", "查找编号"},
		},
		"查找编号只有空白": {
			state(`"  "`, archive(`"id":"  "`)),
